{
  "interpretation": {
    "name": "TightenVariantFastenersLine2",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the fasteners of variant F30 using the MES program, record the result, and return and release the tool.",
    "constraints": [
      "NR7 must be reserved exclusively and released at the end",
      "The tool lease must be renewed before every tool-using step, so those steps depend on reserve-tool",
      "transport-tool must be executed by agvexecutor",
      "NR7 must be at st2 before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program, with no literal numeric values in the recipe",
      "The tightening result must be recorded for traceability"
    ],
    "preference": "Minimise cycle time",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": ["evaluate-tightening"]
  },
  "recipe": {
    "name": "tighten-f30-line2-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f30-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "record",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-f30-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "record",
        "next": "return-tool",
        "steps": [
          {
            "name": "record-result",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
